const items = $input.all().map(i => i.json);
const askedCount = items.length;
const answered = items.filter(a => a.was_asked);
const answeredCount = answered.length;
const tagCounts = {};
for (const a of answered) {
  const tags = a.tags || [];
  for (const t of tags) {
    tagCounts[t] = (tagCounts[t] || 0) + 1;
  }
}
const tagBreakdown = Object.keys(tagCounts).map(k => ({ tag: k, count: tagCounts[k] }));
const sessionAnswersForLlm = answered.map(a => ({ session_answer_id: a.id, session_id: a.session_id, summary: a.summary, tags: a.tags, clips: a.clips }));
return [{ json: { session_answers_for_llm: sessionAnswersForLlm, sessions_asked_count: askedCount, sessions_answered_count: answeredCount, tag_breakdown: tagBreakdown } }];

