const answeredCount = $('Compute Coverage Stats').item.json.sessions_answered_count;
const forceMinority = answeredCount < 3;
const findings = ($input.item.json.findings || []).map(f => ({ ...f, is_minority: forceMinority ? true : f.is_minority }));
return { json: { question_insight_id: $input.item.json.question_insight_id, findings } };

const raw = $input.item.json;
const findingsIn = (raw.output && raw.output.findings) || raw.findings || [];
const questionInsightId = $('Attach Findings').first().json.question_insight_id;
const validIds = new Set(($('Compute Coverage Stats').first().json.session_answers_for_llm || []).map(a => a.session_answer_id));
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const findings = findingsIn
  .map(f => {
    const verifiedIds = (f.session_answer_ids || []).filter(id => uuidRegex.test(id) && validIds.has(id));
    return { ...f, session_answer_ids: verifiedIds };
  })
  .filter(f => f.session_answer_ids.length > 0);
const proposed = findingsIn.length;
const dropped = proposed - findings.length;
return { json: { question_insight_id: questionInsightId, findings: findings, findings_proposed: proposed, findings_dropped: dropped } };

